mapper.select:
SELECT id, channel, external_user_id, email, verification_method,
       verified_at, created_at, updated_at
FROM bot_user_bindings
WHERE channel = #{channel}
  AND external_user_id = #{externalUserId}

mapper.delete:
DELETE FROM bot_user_bindings
WHERE channel = #{channel}
  AND external_user_id = #{externalUserId}
